-- 029 is applied and frozen. Qualify no local output field as a FROM relation.
-- Preserve the restricted worker-only completion signature and all immutable receipts.
CREATE OR REPLACE FUNCTION dg_native_commit_recording(target text,token text,actual_input text,receipt_text text,receipt_digest text,warnings_text text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE t media_transfers%ROWTYPE;r studio_recordings%ROWTYPE;i _dg_native_recording_inputs%ROWTYPE;v jsonb:=receipt_text::jsonb;raw jsonb:=v->'raw';o jsonb:=v->'object';poster jsonb:=v->'poster';at_time text:=dg_utc_now();new_asset text:=v->>'assetId';new_upload text:=v->>'uploadId';
BEGIN
 PERFORM user_id FROM dg_native_locked_membership((SELECT actor_id FROM media_transfers WHERE id=target));SELECT * INTO t FROM media_transfers WHERE id=target FOR UPDATE;SELECT * INTO r FROM studio_recordings WHERE transfer_id=target;SELECT * INTO i FROM _dg_native_recording_inputs WHERE transfer_id=target;
 IF NOT dg_native_recording_valid(target,token,false) OR i.input_hash IS DISTINCT FROM actual_input OR NOT COALESCE(receipt_digest ~ '^[a-f0-9]{64}$',false) OR raw->>'sha256' IS DISTINCT FROM t.expected_sha256 OR(raw->>'size')::bigint IS DISTINCT FROM t.size OR NOT COALESCE(v->>'inputContainer' IN('webm','mp4'),false) OR v->>'expiresAt' IS DISTINCT FROM r.snapshot::jsonb->>'expiresAt' OR(v->>'expiresAt')<=at_time THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Recording completion lost its original, fixed source or lease';END IF;
 IF new_asset IS NULL OR new_upload IS NULL OR NOT COALESCE(raw->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$',false) OR NOT COALESCE(o->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$',false) OR NOT COALESCE(o->>'sha256' ~ '^[a-f0-9]{64}$',false) OR COALESCE((o->>'size')::bigint,0) NOT BETWEEN 32 AND 134217728 OR NOT COALESCE(poster->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$',false) OR NOT COALESCE(poster->>'sha256' ~ '^[a-f0-9]{64}$',false) OR COALESCE((poster->>'size')::bigint,0) NOT BETWEEN 1 AND 8388608 OR jsonb_typeof(v->'specs') IS DISTINCT FROM 'object' OR jsonb_typeof(v->'sourceSpecs') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Recording files need exact bounded private receipts';END IF;
 INSERT INTO _dg_native_recording_receipts VALUES(t.id,r.id,token,i.input_hash,receipt_text,receipt_digest,at_time);
 INSERT INTO uploads VALUES(new_upload,t.tenant_id,t.workspace_id,t.actor_id,o->>'storage_key',o->>'sha256',(o->>'size')::bigint,'video/mp4',(v->'specs')::text,at_time);
 INSERT INTO assets(id,tenant_id,workspace_id,upload_id,name,category,expires_at,created_at) VALUES(new_asset,t.tenant_id,t.workspace_id,new_upload,r.name,'reference',v->>'expiresAt',at_time);
 INSERT INTO _dg_native_asset_origins VALUES(new_asset,new_upload,t.tenant_id,t.workspace_id,o->>'sha256',(o->>'size')::bigint,'recording','mock',t.app_env,at_time);
 INSERT INTO video_sources VALUES(new_asset,poster->>'storage_key',poster->>'sha256',(poster->>'size')::bigint,at_time);
 INSERT INTO studio_recording_outputs VALUES(r.id,t.id,raw->>'storage_key',raw->>'sha256',(raw->>'size')::bigint,v->>'inputContainer',new_asset,o->>'sha256',(o->>'size')::bigint,(v->'sourceSpecs')::text,(v->'specs')::text,at_time);
 INSERT INTO asset_versions VALUES(new_asset,1,jsonb_build_object('id',new_asset,'workspaceId',r.workspace_id,'name',r.name,'category','reference','version',1,'archived',false,'synthetic',false,'expiresAt',v->>'expiresAt','createdAt',at_time,'mediaType','video/mp4','size',(o->>'size')::bigint,'sha256',o->>'sha256','specs',v->'specs')::text,at_time);
 UPDATE media_transfers SET status='ready',asset_id=new_asset,sha256=raw->>'sha256',progress=1,warnings=warnings_text,error_message=NULL,lease_token=NULL,lease_until=NULL,version=version+1,updated_at=at_time WHERE id=target;
 INSERT INTO audit_events VALUES(gen_random_uuid()::text,t.tenant_id,t.workspace_id,t.actor_id,'recording.complete',r.id,'confirmed',token,at_time);RETURN r.id;
END;$dg$;
REVOKE ALL ON FUNCTION dg_native_commit_recording(text,text,text,text,text,text) FROM PUBLIC;
